package com.gymflow.inventory;import org.springframework.data.jpa.repository.JpaRepository;import org.springframework.data.jpa.repository.Lock;import org.springframework.data.jpa.repository.Query;import jakarta.persistence.LockModeType;import java.util.*;public interface StockBalanceRepository extends JpaRepository<StockBalance,UUID>{@Lock(LockModeType.PESSIMISTIC_WRITE)@Query("select s from StockBalance s where s.gym.id=:gymId and s.product.id=:productId")Optional<StockBalance> findLocked(UUID gymId,UUID productId);List<StockBalance> findAllByGym_IdOrderByProduct_Name(UUID gymId);}
